    /**
     * Handles create a Activity.  if not key provided, calls create, otherwise calls save
     * @param		Activity	activity
     * @return		Activity 
     */
	@PostMapping("/create")
    public Activity create( @RequestBody(required=true) CreateActivityCommand command ) {
    	Activity entity = null;

		entity = service.createActivity( command );
		LOGGER.info( "Successfully created Activity with Id " + entity.getActivityId()  );

		return entity;
    }

    /**
     * Handles updating a Activity.  if no key provided, calls create, otherwise calls save
     * @param		Activity activity
     * @return		Activity
     */
	@PutMapping("/update")
    public Activity update( @RequestBody(required=true) UpdateActivityCommand command ) {
		Activity entity = null;

		entity = service.updateActivity(command);
		LOGGER.info( "Successfully updated Activity with Id " + command.getActivityId()  );

		return entity;
	}
 
    /**
     * Handles deleting a Activity entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteActivityCommand command ) {                
		service.delete( command );
		LOGGER.info( "Successfully deleted Activity with Id " + command.getActivityId()  );
	}
	
    /**
     * Handles loading a Activity using a UUID
     * @param		UUID uuid 
     * @return		Activity
     */    
    @GetMapping("/load")
    public Activity load( @RequestParam(required=true) UUID uuid ) {
    	Activity entity = service.getActivity( new ActivityFetchOneSummary( uuid ) );

		LOGGER.info( "Successfully loaded Activity with Id " + uuid   );

        return entity;
    }

    /**
     * Handles loading all Activity business objects
     * @return		Set<Activity>
     */
    @GetMapping("/")
    public List<Activity> loadAll() {                
    	List<Activity> activityList = null;

		activityList = service.getAllActivity();
		LOGGER.info( "successfully loaded all Activitys" );

        return activityList;
                            
    }

